(() => {
  const home = document.getElementById('homeView');
  const view = document.getElementById('routeView');
  const data = {
    eat:{icon:'🍽️',title:'Eat & drink',intro:'From weekday lunch to the table you book months ahead.',subs:['Restaurants','Fika & cafés','Bars','Bakeries','Brunch','Food markets']},
    stay:{icon:'🛏️',title:'Stay',intro:'Hotels, cabins and small places with a reason to stay longer.',subs:['Hotels','Hostels','Cabins','Spa stays','Camping','Unique stays']},
    play:{icon:'🎭',title:'Entertainment',intro:'Films, music, nightlife and culture happening around you.',subs:['Cinema','Live music','Nightlife','Museums','Theatre','Games']},
    explore:{icon:'🧭',title:'Things to do',intro:'Easy weekends, outdoor escapes and plans for any weather.',subs:['Day trips','Outdoors','Family','Tours','Sports','Workshops']},
    wellness:{icon:'🧖',title:'Wellness',intro:'Feel-good places, from a quick haircut to a slow sauna.',subs:['Hair','Spa','Massage','Fitness','Nails','Health']},
    travel:{icon:'🧳',title:'Travel',intro:'Sweden-wide ideas, routes and local recommendations.',subs:['Archipelago','Trains','Nature stays','City breaks','Skiing','Beaches']}
  };
  const places = [];
  const universities = [['Uppsala University','uu.se'],['Lund University','lu.se'],['University of Gothenburg','gu.se'],['Stockholm University','su.se'],['Umeå University','umu.se'],['Linköping University','liu.se'],['Karolinska Institutet','ki.se'],['KTH Royal Institute of Technology','kth.se'],['Luleå University of Technology','ltu.se'],['Karlstad University','kau.se'],['Linnaeus University','lnu.se'],['Örebro University','oru.se'],['Mid Sweden University','miun.se'],['Malmö University','mau.se'],['Swedish University of Agricultural Sciences','slu.se'],['Blekinge Institute of Technology','bth.se'],['Swedish Defence University','fhs.se'],['Swedish School of Sport and Health Sciences','gih.se'],['University of Borås','hb.se'],['Dalarna University','du.se'],['University of Gävle','hig.se'],['Halmstad University','hh.se'],['Kristianstad University','hkr.se'],['University of Skövde','his.se'],['University West','hv.se'],['Mälardalen University','mdu.se'],['Stockholm University of the Arts','uniarts.se'],['Södertörn University','sh.se'],['Chalmers University of Technology','chalmers.se'],['Jönköping University','ju.se'],['Stockholm School of Economics','hhs.se']];
  const jonkopingPlaces = [
    {id:'kapten-kebab',name:'Kapten Kebab',category:'restaurant',type:'Kebab · Falafel · Middle Eastern',address:'Barnarpsgatan 30, 553 16 Jönköping',hours:'Mon–Sat 11:00–20:30 · Sun 12:00–18:30',from:'From 79 SEK',about:'Kebab, falafel and Middle Eastern dishes in central Jönköping.',menu:[['Kebab Box','from 79 SEK'],['Falafel Roll Original','59 SEK'],['Kebab Plate','135 SEK']],demoDeal:'15% Student Deal',img:'assets/food.jpg',website:'https://kaptenkebab.se',source:'Public menu examples checked via Foodora; hours checked via Uber Eats.'},
    {id:'liban-deli',name:'Liban Deli',category:'restaurant',type:'Lebanese · Meze · Catering',address:'Barnarpsgatan 29, 553 16 Jönköping',hours:'Open for lunch and dinner · check website for today’s hours',from:'Nearly 30 hot and cold meze',about:'Authentic Lebanese food made from high-quality ingredients, with meze, skewers, takeaway and catering.',menu:[['Classic hummus','Public menu item'],['Falafel','Public menu item'],['Two skewers with side','Public menu item']],demoDeal:'Free coffee with lunch',img:'assets/businesses/liban-deli.jpg',website:'https://www.libandeli.com',source:'Description, address, menu examples and image from Liban Deli’s official website / Jönköping visitor guide.'},
    {id:'aqua',name:'AQUA Dinner & Drinks',category:'restaurant',type:'Lunch · Dinner · Seafood',address:'Barnarpsgatan 24, 553 16 Jönköping',hours:'Mon–Thu 11:30–14:30, 17:00–22:00 · Fri 11:30–23:00 · Sat 12:00–23:00 · Sun 12:00–20:00',from:'Lunch from 149 SEK',about:'A central restaurant serving weekday lunch, dinner and weekend menus.',menu:[['Weekday lunch','149 SEK'],['Schnitzel','159 SEK'],['Vegan burger with fries','149 SEK']],demoDeal:'20% off quiet hours',img:'assets/businesses/aqua.webp',website:'https://www.aquadinner.se',source:'Current examples and hours from AQUA’s official public lunch page; image from Jönköping’s official visitor guide.'},
    {id:'munken',name:'Restaurang Munken',category:'restaurant',type:'Restaurant · Pizza · Meze',address:'Barnarpsgatan 100, 553 33 Jönköping',hours:'Mon–Fri 16:00–21:00 · Sat 12:00–21:00 · Sun 12:00–20:00',from:'Falafel from 69 SEK',about:'A neighbourhood restaurant with pizza, meze, vegetarian and gluten-free choices.',menu:[['Falafel, 6 pcs','69 SEK'],['Cheese rolls, 4 pcs','79 SEK'],['Kebab pizza','149 SEK']],demoDeal:'15% Student Deal',img:'assets/businesses/munken.webp',website:'https://www.munkenjkpg.com',source:'Menu, address, hours and image from the restaurant’s official website.'},
    {id:'napoleon',name:'Konditori Napoleon',category:'cafe',type:'Bakery · Café · Cakes',address:'Barnarpsgatan 17, 553 16 Jönköping',hours:'Mon–Fri 06:00–18:00 · Sat 07:30–15:00 · Sun closed',from:'Fresh bakery daily',about:'A long-standing central bakery and café offering bread, cakes, pastries and savoury catering.',menu:[['Hamburger buns, 5-pack','55 SEK'],['Mini hamburger buns, 10-pack','79 SEK'],['Whole savoury pie, 4–5 people','289 SEK']],demoDeal:'Coffee with any pastry',img:'assets/businesses/napoleon.jpeg',website:'https://konditorinapoleon.se',source:'Address, hours, example prices and image from the bakery’s official website and public menu PDF.'},
    {id:'quality-match',name:'Quality Hotel Match',category:'hotel',type:'Hotel',address:'Brånebacken 4, 553 15 Jönköping',hours:'Reception and current availability via official website',from:'Live room price on website',about:'A city hotel beside Lake Vättern, Jönköping Centralstation and the historic Matchstick Area.',menu:[],demoDeal:'Member room upgrade',img:'assets/businesses/quality-match.webp',website:'https://www.strawberry.se/hotell/sverige/jonkoping/quality-hotel-match/',source:'Address, hotel information and image from the official Jönköping visitor guide and hotel website.'},
    {id:'vatterstranden',name:'Vätterstranden',category:'explore',type:'Beach · Lakeside walk',address:'Vätterstranden, Jönköping',hours:'Public outdoor area',from:'Free',about:'A long urban beach and lakeside route on Lake Vättern.',menu:[],demoDeal:'Free local activity',img:'assets/archipelago.jpg',website:'https://jkpg.com',source:'Public place information from Jönköping’s official visitor guide.'}
  ];
  jonkopingPlaces.forEach(p=>p.maps='https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(p.name+', '+p.address));
  places.splice(0,places.length,...['liban-deli','aqua','napoleon','quality-match'].map(id=>jonkopingPlaces.find(p=>p.id===id)));
  const crumbs = (...items) => '<div class="crumbs"><button data-go="home">Home</button><span>›</span>'+items.map((x,i)=>i===items.length-1?'<span>'+x+'</span>':'<button data-go="'+x.toLowerCase()+'">'+x+'</button><span>›</span>').join('')+'</div>';
  const shell = body => '<section class="subpage"><div class="wrap">'+body+'</div></section>';
  const card = p => '<article class="result-card clickable" tabindex="0" data-go="'+(p.id?'jonkoping-place':'place')+'" '+(p.id?'data-id="'+p.id+'"':'')+'><img src="'+p.img+'" alt=""><div class="result-copy"><div class="place-top"><h3>'+p.name+'</h3>'+(p.score?'<b>★ '+p.score+'</b>':'')+'</div><p class="meta">'+p.type+(p.reviews?' · '+p.reviews:'')+'</p>'+(p.address?'<span class="business-card-address">'+p.address+'</span>':'')+(p.demoDeal?'<span class="demo-offer">Demo offer · '+p.demoDeal+'</span>':'')+'<div class="price">'+(p.from||p.deal||'View current information')+'</div><div class="touch-actions"><button data-go="'+(p.id?'jonkoping-place':'place')+'" '+(p.id?'data-id="'+p.id+'"':'')+'>View details</button><button data-save>Save</button>'+(p.maps?'<button class="primary" data-map-choice data-address="'+p.address+'" data-google="'+p.maps+'">Directions</button>':'<button class="primary" data-go="payment">Book</button>')+'</div></div></article>';
  const templates = {
    discover: () => shell(crumbs('Discover')+'<div class="route-hero"><div><div class="eyebrow"><span class="dot"></span>DISCOVER JÖNKÖPING</div><h1>What do you feel like doing?</h1><p>Browse local essentials, student life and the plans happening around campus.</p></div><input class="route-search" data-search-route placeholder="Search all categories…"></div><div class="journey-grid">'+['eat','stay','play','explore'].map(k=>{const x=data[k];return '<article class="journey clickable" tabindex="0" data-go="category" data-type="'+k+'"><div class="journey-icon">'+x.icon+'</div><div><h3>'+x.title+'</h3><p>'+x.intro+'</p></div><span class="journey-arrow">→</span></article>'}).join('')+'</div><div class="campus-zone"><div class="section-head"><div><h2>Campus & student life</h2><p>Discover activities, welcome-week plans and student-only offers.</p></div></div><div class="campus-grid"><button class="campus-card featured clickable" data-go="campaign"><div><span class="tag">JÖNKÖPING</span><h3>Campus activities</h3><p>Local events, pop-ups and ways to meet people around university life.</p></div><span class="journey-arrow">→</span></button><button class="campus-card clickable" data-go="student"><div><span class="tag">STUDENT DEALS</span><h3>Freshers, look here</h3><p>Verify your student status and preview the monthly deal wallet.</p></div><span class="journey-arrow">→</span></button><button class="campus-card coming" type="button"><div><span class="tag">COMING SOON</span><h3>Nearby on campus</h3><p>University collaborations and offline experiences are being prepared.</p></div><span class="journey-arrow">•••</span></button></div></div><div class="section-head" style="margin-top:54px"><div><h2>More to explore</h2><p>Wellness, travel and local experiences.</p></div></div><div class="subcats">'+['wellness','travel'].map(k=>'<button class="subcat clickable" data-go="category" data-type="'+k+'"><span>'+data[k].icon+'</span><b>'+data[k].title+'</b></button>').join('')+'</div>'),
    category: q => {const x=data[q.type]||data.eat;return shell(crumbs('Discover',x.title)+'<div class="route-hero"><div><div class="journey-icon">'+x.icon+'</div><h1>'+x.title+'</h1><p>'+x.intro+'</p></div><input class="route-search" data-search-route placeholder="Search in Jönköping…"></div><div class="subcats" style="margin:0 0 34px">'+x.subs.map(s=>'<button class="subcat clickable" data-go="listing" data-type="'+q.type+'"><span>○</span><b>'+s+'</b></button>').join('')+'</div><div class="layout-two"><aside class="filter-panel"><h4>Filter</h4><label><input type="checkbox"> Open now</label><label><input type="checkbox"> Demo deals</label><label><input type="checkbox"> Central Jönköping</label><h4 style="margin-top:22px">Price</h4><label><input type="radio" name="p"> Any price</label><label><input type="radio" name="p"> Under 200 kr</label></aside><div><div class="section-head"><div><h2>Recommended in Jönköping</h2><p>Real local examples with publicly listed information</p></div></div><div class="results-grid">'+places.map(card).join('')+'</div></div></div>');},
    listing: q => templates.category(q),
    place: () => templates['jonkoping-place']({id:'liban-deli'}),
    deals: () => shell(crumbs('Deals')+'<div class="route-hero"><div><div class="eyebrow"><span class="dot"></span>MEMBER PRICES</div><h1>Better plans, smaller bill.</h1><p>Live restaurant tables, experiences and services with prices available only through nearby.</p></div></div><div class="filters"><button class="filter active">All deals</button><button class="filter">Tonight</button><button class="filter">Food</button><button class="filter">Things to do</button></div><div class="results-grid">'+places.map(card).join('')+'</div>'),
    search: q => {const term=(q.q||'').trim().toLowerCase();const all=[...places,...jonkopingPlaces];const found=term?all.filter(p=>[p.name,p.type,p.address,p.deal,p.demoDeal,p.category,p.about,p.hours,...(p.menu||[]).flat()].filter(Boolean).join(' ').toLowerCase().includes(term)):all;return shell(crumbs('Search')+'<div class="route-hero"><div><div class="eyebrow"><span class="dot"></span>SEARCH NEARBY</div><h1>'+(term?'Results for “'+q.q+'”':'Explore nearby')+'</h1><p>'+found.length+' matching places across names, categories, streets, menus and offers.</p></div><input class="route-search" data-search-route value="'+(q.q||'')+'" placeholder="Restaurant, falafel, Barnarpsgatan, hotel…"></div>'+(found.length?'<div class="results-grid">'+found.map(card).join('')+'</div>':'<div class="empty-state"><b>No exact match yet.</b><p>Try “restaurant”, “falafel”, “student”, “Barnarpsgatan”, “hotel” or “fika”.</p><button class="pill-btn" data-go="discover">Browse categories</button></div>'));},
    community: () => shell(crumbs('Community')+'<div class="route-hero"><div><div class="eyebrow"><span class="dot"></span>JÖNKÖPING STORIES</div><h1>Recommendations from around the lake city.</h1><p>Save lists and share the real local places you would tell a friend about.</p></div><button class="pill-btn">Create a post</button></div><div class="post-composer"><span class="comment-avatar">A</span><input placeholder="Share a Jönköping place or local tip…"><button class="pill-btn">Post</button></div><div class="story-feed"><article class="story-tile clickable" tabindex="0" data-go="story"><img src="assets/businesses/liban-deli.jpg" alt="Liban Deli food"><div><small>FOOD GUIDE · JÖNKÖPING</small><h3>A student-friendly food walk near JU</h3><p>Elin · Community mockup</p></div></article><article class="story-tile clickable" tabindex="0" data-go="story"><img src="assets/businesses/napoleon.jpeg" alt="Konditori Napoleon"><div><small>FIKA</small><h3>A classic fika stop on Barnarpsgatan</h3><p>Max · Community mockup</p></div></article><article class="story-tile clickable" tabindex="0" data-go="story"><img src="assets/businesses/quality-match.webp" alt="Quality Hotel Match"><div><small>WEEKEND</small><h3>Lake views and the Matchstick Area at sunset</h3><p>Aisha · Community mockup</p></div></article></div>'),
    story: () => shell(crumbs('Community','Jönköping food guide')+'<article class="article"><img class="detail-cover" src="assets/businesses/liban-deli.jpg" alt="Food at Liban Deli"><h1>A student-friendly food walk near JU</h1><p class="meta">Community mockup · Jönköping <span class="sv-badge">Translated automatically</span></p><p>Start around the university, walk towards Barnarpsgatan and compare real public menus before choosing a place.</p><div class="article-callout"><b>1 · Liban Deli</b><p>Lebanese meze in central Jönköping. Check current information on the business website.</p><button class="text-link" data-go="jonkoping-place" data-id="liban-deli">View place →</button></div><p>Continue to Konditori Napoleon for a classic fika stop, then finish beside Lake Vättern.</p><div class="comment-box"><h3>Comments</h3><div class="post-composer" style="margin:14px 0"><span class="comment-avatar">A</span><input placeholder="Add a comment…"><button class="pill-btn">Reply</button></div></div></article>'),
    cities: () => templates.jonkoping(),
    city: () => templates.jonkoping(),
    jonkoping: () => shell(crumbs('Cities','Jönköping')+'<div class="route-hero"><div><div class="eyebrow"><span class="dot"></span>REAL LOCAL BUSINESS DATA</div><h1>Jönköping by the lake.</h1><p>Explore publicly listed local businesses, prices and addresses. Example NEARBY offers are always clearly marked.</p></div></div><div class="mobile-map" aria-label="Jönköping business map preview"><div class="map-water"></div><button class="map-pin-btn" data-map-preview="kapten-kebab" aria-label="Show Kapten Kebab"><span>1</span></button><button class="map-pin-btn" data-map-preview="liban-deli" aria-label="Show Liban Deli"><span>2</span></button><button class="map-pin-btn" data-map-preview="aqua" aria-label="Show AQUA"><span>3</span></button><div class="map-preview" id="mapPreview"><img src="assets/food.jpg" alt=""><div><b>Kapten Kebab</b><small>Kebab · Barnarpsgatan 30</small></div><button data-go="jonkoping-place" data-id="kapten-kebab" aria-label="Open place">→</button></div></div><div class="real-data-note"><b>Real public information</b> — addresses, listed hours and menu examples are sourced from public business pages. Prices may change. <b>Demo offers are concept-only.</b></div><div class="subcats" style="margin:0 0 36px">'+[['🍽️','Restaurants','restaurant'],['🛏️','Hotels','hotel'],['☕','Fika','cafe'],['🌊','Things to do','explore']].map(x=>'<button class="subcat clickable" data-go="jonkoping-list" data-type="'+x[2]+'"><span>'+x[0]+'</span><b>'+x[1]+'</b></button>').join('')+'</div><div class="section-head"><div><h2>Local Jönköping businesses</h2><p>View public information, save a place or open turn-by-turn directions.</p></div></div><div class="results-grid">'+jonkopingPlaces.map(card).join('')+'</div>'),
    'jonkoping-list': q => {const selected=jonkopingPlaces.filter(p=>p.category===(q.type||'restaurant'));const title={restaurant:'Restaurants',hotel:'Hotels',cafe:'Fika',explore:'Things to do'}[q.type]||'Places';return shell(crumbs('Cities','Jönköping',title)+'<div class="route-hero"><div><div class="eyebrow"><span class="dot"></span>JÖNKÖPING</div><h1>'+title+'</h1><p>Public business information with clearly separated concept offers.</p></div><input class="route-search" data-search-route placeholder="Search name, street, menu…"></div><div class="results-grid">'+selected.map(card).join('')+'</div>');},
    'jonkoping-place': q => {const p=jonkopingPlaces.find(x=>x.id===q.id)||jonkopingPlaces[0];const menu=p.menu.length?'<div class="menu-list">'+p.menu.map(x=>'<div class="menu-item"><span>'+x[0]+'</span><b>'+x[1]+'</b></div>').join('')+'</div>':'<p class="meta">See the official website for current availability and prices.</p>';return shell(crumbs('Cities','Jönköping',p.name)+'<div class="detail-grid"><article class="detail-main"><img class="detail-cover" src="'+p.img+'" alt="Illustrative local business photo"><div class="detail-body"><div class="detail-title"><div><h1>'+p.name+'</h1><p class="meta">'+p.type+'</p></div></div><div class="tag-row"><span class="tag">Real public information</span><span class="tag">Auto-translated</span></div><h2 style="margin-top:30px">About</h2><p>'+p.about+'</p><h2 style="margin-top:30px">Menu / popular examples</h2>'+menu+'<p class="source-note">Prices are public examples and may change. Please confirm with the business before ordering.</p><h2 style="margin-top:30px">Example NEARBY deal</h2><p><span class="demo-offer">Demo offer</span></p><h3>'+p.demoDeal+'</h3><p class="meta">Concept preview only — this is not presented as a confirmed offer from '+p.name+'.</p><div class="detail-actions"><a class="pill-btn" data-direct-map href="'+p.maps+'" target="_blank" rel="noopener">Get directions</a><button class="pill-btn light" data-save>Save</button><a class="pill-btn light" href="'+p.website+'" target="_blank" rel="noopener">Visit website</a></div></div></article><aside class="booking-card"><span class="tag">LOCATION</span><h3 style="margin-top:15px">'+p.name+'</h3><div class="address-row"><span><small>ADDRESS</small><b>'+p.address+'</b></span><button class="nav-icon" data-map-choice data-address="'+p.address+'" data-google="'+p.maps+'" aria-label="Choose navigation app" title="Navigate">➤</button></div><h4>PUBLIC OPENING HOURS</h4><p>'+p.hours+'</p><p class="source-note">'+p.source+'</p></aside></div>');},
    ai: q => {const prompt=q.prompt||'Plan my afternoon';return shell('<div class="ai-planner-shell">'+crumbs('AI Plan')+'<div class="route-hero"><div><div class="eyebrow"><span class="dot"></span>NEARBY AI PLANNER</div><h1>Your next few hours, sorted.</h1><p>Ask naturally. Nearby balances distance, budget, opening hours and member deals.</p></div></div><div class="chat"><div class="chat-head"><span class="ai-face">✦</span><div><strong>nearby AI</strong><div class="online">● Ready</div></div></div><div class="bubble user">'+prompt+'</div><div class="bubble bot">Here is a simple plan near you with two deals and less than 20 minutes of walking.</div><div class="ai-prompt-grid"><button data-ai-plan="Plan my afternoon">Plan my afternoon</button><button data-ai-plan="Cheap food near JU">Cheap food near JU</button><button data-ai-plan="What can I do tonight?">What can I do tonight?</button><button data-ai-plan="Plan something under 200 SEK">Under 200 SEK</button></div></div><div class="ai-plan-result" id="aiPlanResult"><span class="tag">3 STOPS · 186 SEK · 2H 40M</span><h2 style="margin:15px 0">A low-cost Jönköping afternoon</h2><div class="plan-step"><span>1</span><div><b>Heddagretas Café</b><small>Fika · 6 min walk · Student price 49 kr</small></div><button data-go="jonkoping-place" data-id="heddagretas">View</button></div><div class="plan-step"><span>2</span><div><b>Vätterstranden</b><small>Lakeside walk · Free · 45 min</small></div><button data-go="jonkoping-place" data-id="vatterstranden">View</button></div><div class="plan-step"><span>3</span><div><b>Kappa Bar</b><small>Food & games · Deal from 137 kr</small></div><button data-go="jonkoping-place" data-id="kappa-bar">View</button></div><div class="plan-footer"><button class="pill-btn light" data-save>♡ Save plan</button><button class="pill-btn" data-go="jonkoping">View route</button></div></div></div>');},
    profile: () => shell(crumbs('Profile')+'<div class="account-shell"><section class="profile-card auth-card"><span class="tag">YOUR NEARBY ACCOUNT</span><h1>Sign in or create an account.</h1><p class="meta">Save places, unlock member prices and keep rewards in one place.</p><div class="verify-tabs"><button class="verify-tab active" data-auth-tab="signin">Sign in</button><button class="verify-tab" data-auth-tab="create">Create account</button></div><div class="auth-fields"><label>Email</label><input type="email" placeholder="you@example.com"><label>Password</label><input type="password" placeholder="••••••••"><button class="wide-action" data-auth-continue>Continue</button></div><div class="auth-divider">or</div><button class="social-auth">Continue with Apple</button><button class="social-auth">Continue with Google</button></section><section class="profile-card profile-editor"><div class="profile-avatar" id="profileAvatar">A</div><h2 id="profileName">Alex</h2><p class="meta">Profile preview · content coming soon</p><label>Display name</label><input id="profileNameInput" value="Alex"><label>Avatar</label><div class="avatar-options"><button data-avatar="A">A</button><button data-avatar="🌿">🌿</button><button data-avatar="☕">☕</button><button data-avatar="🎓">🎓</button></div><button class="pill-btn" data-save-profile>Save profile</button><div class="pro-entry"><span><b>nearby Pro</b><small>Extra deals, points and member rewards</small></span><button class="pill-btn" data-go="membership">View Pro</button></div></section></div>'),
    membership: () => shell(crumbs('Profile','nearby Pro')+'<div class="pro-hero"><div><span class="tag">NEARBY PRO</span><h1>More deals. More rewards.</h1><p>Unlock member-only prices, monthly rewards and priority access to student and city campaigns.</p><button class="pill-btn" data-go="pro-checkout" data-type="user">Unlock user Pro</button></div><div class="pro-price"><b>49 kr</b><span>/ month</span><small>Cancel anytime</small></div></div><div class="benefit-grid"><article><b>Up to 30% off</b><span>Around you every week</span></article><article><b>2× points</b><span>On eligible bookings</span></article><article><b>Early access</b><span>Campaigns and campus events</span></article></div>'),
    'pro-checkout': q => {const business=q.type==='business';return shell(crumbs(business?'For businesses':'Profile',business?'Business Pro':'nearby Pro')+'<div class="checkout"><form><span class="tag">'+(business?'BUSINESS PRO':'NEARBY PRO')+'</span><h1 style="font-size:42px;margin:16px 0">Unlock '+(business?'business insights':'member rewards')+'.</h1><p class="meta">'+(business?'Advanced analytics, campaign controls and priority discovery.':'Exclusive offers, points and priority campaign access.')+'</p><div class="plan-choice active"><span><b>Monthly</b><small>Cancel anytime</small></span><b>'+(business?'399':'49')+' kr</b></div><h2 style="margin-top:28px">Payment method</h2><div class="payment-methods"><button type="button" class="pay-method active" data-method="Card"><span class="pay-logo">VISA</span><span><b>Credit or debit card</b><small>Secure card payment</small></span></button><button type="button" class="pay-method" data-method="Swish"><span class="pay-logo">Swish</span><span><b>Swish</b><small>Confirm in the Swish app</small></span></button><button type="button" class="pay-method" data-method="Klarna"><span class="pay-logo">Klarna.</span><span><b>Klarna</b><small>Pay now or later</small></span></button><button type="button" class="pay-method" data-method="Apple Pay"><span class="pay-logo"> Pay</span><span><b>Apple Pay</b><small>Fast checkout</small></span></button></div><button type="button" class="wide-action" data-pro-unlock="'+(business?'business':'user')+'">Start '+(business?'Business Pro':'Nearby Pro')+'</button></form><aside class="order"><h3>Your plan</h3><div class="order-row"><span>'+ (business?'Business Pro':'Nearby Pro') +'</span><b>'+(business?'399':'49')+' kr/month</b></div><div class="order-row"><span>Today</span><b>'+(business?'399':'49')+' kr</b></div><p class="translation-note">Subscription renews monthly until cancelled.</p></aside></div>');},
    student: () => shell(crumbs('Student discounts')+'<div class="route-hero student-hero"><div><div class="eyebrow"><span class="dot"></span>NEARBY STUDENT</div><h1>More city. Less student budget.</h1><p>Verify once and unlock a fresh pack of nearby discounts every month.</p></div><span class="student-pass">STUDENT<br><b>PASS</b></span></div><div class="verify-layout"><section class="verify-card"><span class="tag">STEP 1 · VERIFY</span><h2>Choose how to verify</h2><div class="verify-tabs"><button class="verify-tab active" data-verify="email">School email</button><button class="verify-tab" data-verify="upload">Student ID</button></div><div id="verifyEmail" class="verify-panel"><label>School email address</label><div class="verify-input"><input type="email" placeholder="name@university.se"><button class="pill-btn" data-verify-submit>Send code</button></div><p class="meta">We accept active university and college email domains.</p></div><div id="verifyUpload" class="verify-panel" hidden><label>Upload your student ID</label><button class="upload-zone" data-upload-student><b>＋ Choose student ID</b><span>JPG, PNG or PDF · Details are reviewed securely</span></button></div></section><aside class="student-summary"><span class="tag">MONTHLY DROP</span><h2>New deals every month</h2><p>Verified students receive a rotating wallet of local coupons.</p><div class="coupon-mini"><b>30% off dinner</b><span>Sun–Thu · selected restaurants</span></div><div class="coupon-mini"><b>2-for-1 cinema</b><span>One use this month</span></div><div class="coupon-mini"><b>49 kr fika</b><span>Coffee + bun nearby</span></div></aside></div><div class="section-head" style="margin-top:54px"><div><h2>This month’s student deals</h2><p>Preview the offers waiting after verification.</p></div></div><div class="coupon-grid"><article class="coupon"><span>FOOD</span><h3>30% off your table</h3><p>Participating restaurants · Sunday–Thursday</p><b>VERIFY TO UNLOCK</b></article><article class="coupon"><span>TRAVEL</span><h3>100 kr off a city trip</h3><p>Selected student routes and weekend stays</p><b>MONTHLY CODE</b></article><article class="coupon"><span>WELLNESS</span><h3>Student reset for 199 kr</h3><p>Selected gyms, saunas and salons</p><b>LIMITED SPOTS</b></article></div>'),
    business: () => shell(crumbs('For businesses')+'<div class="promo-banner"><div><span class="tag">2 MONTHS FREE</span><h2 style="margin-top:15px">Join nearby and get discovered faster.</h2><p>Start with the core business tools free for two months, then choose the plan that fits.</p><div class="merchant-actions"><button class="pill-btn" data-merchant-open style="background:var(--green);color:var(--ink)">Start 2 months free</button><button class="pill-btn" data-go="pro-checkout" data-type="business" style="background:#fff;color:var(--ink)">Unlock Business Pro</button><button class="pill-btn light" data-go="business-dashboard" style="border-color:#fff;color:#fff">View Pro insights</button></div></div><div class="promo-perks"><div class="promo-perk"><b>2× local reach</b><br>Priority placement nearby</div><div class="promo-perk"><b>Pro analytics</b><br>Customer and campaign insights</div><div class="promo-perk"><b>Smart campaigns</b><br>Control traffic by time</div><div class="promo-perk"><b>Revenue view</b><br>Track platform sales</div></div></div><div class="route-hero"><div><div class="eyebrow"><span class="dot"></span>NEARBY FOR BUSINESS</div><h1>Turn nearby interest into real visits.</h1><p>Manage your page, publish offers, respond to translated reviews and understand what local customers want.</p></div><button class="pill-btn" data-merchant-open>List your business</button></div><div class="journey-grid"><article class="journey"><div class="journey-icon">◌</div><div><h3>Your page</h3><p>Hours, menu, services, photos and verified information.</p></div></article><article class="journey"><div class="journey-icon">%</div><div><h3>Smart offers</h3><p>Fill quiet times without discounting everything.</p></div></article><article class="journey"><div class="journey-icon">☆</div><div><h3>Reviews</h3><p>Reply once; customers read it in their language.</p></div></article><article class="journey"><div class="journey-icon">↗</div><div><h3>Pro Insights</h3><p>Audience, searches, saves, bookings and repeat visits.</p></div></article></div>'),
    'business-dashboard': () => shell(crumbs('For businesses','Pro Insights')+'<div class="dashboard-head"><div><span class="tag">BUSINESS PRO · ACTIVE</span><div class="eyebrow" style="margin-top:14px"><span class="dot"></span>STUDIO FORM · LIVE</div><h1>Your business at a glance.</h1><p>Understand customers, control visibility and see what nearby generates for you.</p></div><button class="pill-btn" data-go="business">Manage business page</button></div><div class="metric-grid"><article class="metric"><span>Profile views</span><b>18,420</b><small>↑ 24% this month</small></article><article class="metric"><span>Visits from nearby</span><b>1,284</b><small>↑ 16% this month</small></article><article class="metric"><span>Platform revenue</span><b>84,260 kr</b><small>After discounts</small></article><article class="metric"><span>Bookings</span><b>392</b><small>31% repeat guests</small></article></div><div class="insight-callout"><b>Pro insight</b><span>Students near Jönköping University save lunch deals 2.4× more often between 11:00–13:00.</span></div><div class="dashboard-grid"><section class="dashboard-panel"><div class="section-head"><div><h2>Traffic control</h2><p>Choose where to focus this week.</p></div></div><div class="traffic-control"><div><b>Nearby discovery boost</b><span>More visibility within 3 km</span></div><button class="toggle active" aria-label="Toggle nearby boost"></button></div><div class="traffic-control"><div><b>Lunch campaign</b><span>Weekdays · 11:00–14:00</span></div><button class="toggle active" aria-label="Toggle lunch campaign"></button></div><div class="traffic-control"><div><b>Student deal</b><span>Reach verified students nearby</span></div><button class="toggle" aria-label="Toggle student deal"></button></div></section><section class="dashboard-panel"><h2>Revenue this month</h2><div class="revenue-chart"><i style="height:32%"></i><i style="height:48%"></i><i style="height:42%"></i><i style="height:68%"></i><i style="height:59%"></i><i style="height:82%"></i><i style="height:74%"></i></div><div class="revenue-row"><span>Gross sales</span><b>112,480 kr</b></div><div class="revenue-row"><span>Discounts funded</span><b>−18,220 kr</b></div><div class="revenue-row"><span>Platform fees</span><b>−10,000 kr</b></div><div class="revenue-row total"><span>Your revenue</span><b>84,260 kr</b></div></section></div>'),
    campaign: () => shell(crumbs('Discover','Campus activities')+'<div class="campaign-hero"><span class="tag">JÖNKÖPING · COMING SOON</span><h1>Nearby is coming to campus.</h1><p>Pop-ups, welcome-week discovery and offline activities are being prepared with Swedish university communities.</p><div class="campaign-actions"><button class="pill-btn" data-go="student">Get student access</button><button class="pill-btn light" data-go="discover">Back to Discover</button></div></div><div class="section-head"><div><h2>What to expect</h2><p>Early concepts for the campus launch.</p></div></div><div class="campus-grid"><article class="campus-card featured"><div><span class="tag">WELCOME WEEK</span><h3>Meet nearby</h3><p>Discover local places and new people through guided campus activities.</p></div></article><article class="campus-card"><div><span class="tag">LOCAL BUSINESS</span><h3>Campus pop-ups</h3><p>Food, fika and student-friendly local brands in one place.</p></div></article><article class="campus-card coming"><div><span class="tag">COMING SOON</span><h3>University collaborations</h3><p>More details will be announced as campaigns are confirmed.</p></div></article></div><div class="section-head" style="margin-top:48px"><div><h2>University network preview</h2><p>Institutions shown as a concept network, not confirmed partnerships.</p></div></div><div class="university-grid">'+universities.map((u,i)=>'<article class="uni-card"><div class="uni-mark"><img src="https://www.google.com/s2/favicons?domain_url=https://'+u[1]+'&sz=128" alt="'+u[0]+' brand icon"><span>'+u[0].split(' ').filter(w=>!['of','the','and'].includes(w.toLowerCase())).slice(0,3).map(w=>w[0]).join('')+'</span></div><b>'+u[0]+'</b><span>'+(i%3===0?'Welcome week concept':i%3===1?'Student deal concept':'Campus event concept')+'</span></article>').join('')+'</div>'),
    payment: () => shell(crumbs('Lilla Ego','Checkout')+'<div class="route-hero"><div><h1>Confirm your booking</h1><p>Your 30% restaurant discount is reserved for the next 08:42.</p></div></div><div class="checkout"><form><h2>Contact details</h2><div class="field"><label>Name</label><input value="Alex Andersson"></div><div class="field"><label>Email</label><input value="alex@example.com"></div><div class="field"><label>Mobile number</label><input placeholder="+46"></div><h2 style="margin-top:28px">Choose payment method</h2><p class="meta">Payment partners may add an extra offer to your nearby member discount.</p><div class="payment-methods"><button type="button" class="pay-method active" data-method="Card"><span class="pay-logo">VISA</span><span><b>Credit or debit card</b><small>Extra 5% with selected Nordic cards</small></span></button><button type="button" class="pay-method" data-method="Swish"><span class="pay-logo">Swish</span><span><b>Swish</b><small>Get 20 kr cashback today</small></span></button><button type="button" class="pay-method" data-method="Klarna"><span class="pay-logo">Klarna.</span><span><b>Klarna</b><small>Pay later · 0% interest for 30 days</small></span></button><button type="button" class="pay-method" data-method="Revolut"><span class="pay-logo">Revolut</span><span><b>Revolut Pay</b><small>3× RevPoints on this booking</small></span></button><button type="button" class="pay-method" data-method="Alipay"><span class="pay-logo">Alipay</span><span><b>Alipay</b><small>Save 25 kr on eligible international payments</small></span></button><button type="button" class="pay-method" data-method="Kakao Pay"><span class="pay-logo">Kakao</span><span><b>Kakao Pay</b><small>5% cashback for eligible Korean travellers</small></span></button><button type="button" class="pay-method" data-method="PayPay"><span class="pay-logo">PayPay</span><span><b>PayPay</b><small>Earn bonus points on eligible Japan accounts</small></span></button><button type="button" class="pay-method" data-method="Apple Pay"><span class="pay-logo"> Pay</span><span><b>Apple Pay</b><small>Fast checkout · 10 kr cashback</small></span></button></div><div class="method-fields"><div class="field"><label>Card number</label><input placeholder="•••• •••• •••• ••••"></div></div><button type="button" class="wide-action" id="confirmBooking">Confirm with Card</button></form><aside class="order"><span class="tag">DEAL STACKED</span><h3 style="margin-top:14px">Lilla Ego</h3><p class="meta">Tomorrow · 17:30 · 2 guests</p><div class="order-row"><span>Estimated food total</span><span>800 kr</span></div><div class="order-row"><span>Nearby discount</span><span style="color:var(--green-dark)">−240 kr</span></div><div class="order-row"><span>Card partner offer</span><span style="color:var(--green-dark)">−28 kr</span></div><div class="order-row order-total"><span>Estimated total</span><span>532 kr</span></div><p class="meta">You pay securely through your selected provider.</p></aside></div>')
  };
  templates.payment = () => templates['pro-checkout']({type:'user'});
  function params(){return Object.fromEntries(new URLSearchParams(location.search));}
  function navigate(route, extra={}){const q=new URLSearchParams({view:route,...extra});history.pushState({},'',location.pathname+'?'+q);render();}
  let selectedLang=localStorage.getItem('nearby-language')||'en';
  function render(){const q=params();const group={category:'discover',listing:'discover',place:'discover',cities:'discover',city:'discover',jonkoping:'discover','jonkoping-list':'discover','jonkoping-place':'discover',campaign:'discover',search:'discover',payment:'deals',student:'profile',membership:'profile','pro-checkout':'profile','business-dashboard':'profile'};const current=group[q.view]||q.view||'home';document.querySelectorAll('.mobile-tabbar .tab-item').forEach(x=>x.classList.toggle('active',x.dataset.go===current));if(!q.view){home.hidden=false;view.hidden=true}else{home.hidden=true;view.hidden=false;view.innerHTML=(templates[q.view]||templates.discover)(q);scrollTo({top:0,behavior:'smooth'})}applyLanguage(selectedLang);}
  document.addEventListener('click',e=>{if(e.target.closest('[data-save],.heart,[data-map-choice],[data-direct-map],a[target="_blank"]'))return;const go=e.target.closest('[data-go]');if(go){e.preventDefault();const r=go.dataset.go;if(r==='home'){history.pushState({},'',location.pathname);render()}else navigate(r,{...(go.dataset.type?{type:go.dataset.type}:{}),...(go.dataset.id?{id:go.dataset.id}:{}),...(go.dataset.prompt?{prompt:go.dataset.prompt}:{})})}});
  document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.clickable[data-go]'))e.target.click();if(e.key==='Enter'&&e.target.matches('[data-search-route]'))navigate('search',{q:e.target.value.trim()})});
  document.querySelector('.brand-lockup').addEventListener('click',e=>{e.preventDefault();history.pushState({},'',location.pathname);render()});
  const navRoutes=['discover','deals','community','cities'];document.querySelectorAll('.links a').forEach((a,i)=>{a.dataset.route=navRoutes[i];a.onclick=e=>{e.preventDefault();navigate(a.dataset.route)}});
  document.querySelectorAll('.cat').forEach((b,i)=>{const keys=['eat','eat','wellness','explore','travel','play'];b.dataset.go='category';b.dataset.type=keys[i];b.classList.add('clickable')});
  document.querySelectorAll('.place').forEach(p=>{if(!p.dataset.go)p.dataset.go='place';p.classList.add('clickable');p.tabIndex=0});
  document.querySelectorAll('.story').forEach(p=>{p.dataset.go='story';p.classList.add('clickable');p.tabIndex=0});
  document.querySelectorAll('.city').forEach(p=>{if(!p.dataset.go)p.dataset.go='city';p.classList.add('clickable')});
  document.querySelectorAll('#homeView .text-link').forEach(a=>{const t=a.textContent;a.onclick=e=>{e.preventDefault();navigate(t.includes('categor')?'discover':t.includes('deal')?'deals':'community')}});
  document.querySelectorAll('.nav-actions .pill-btn.light').forEach(b=>b.onclick=()=>navigate('business'));
  document.querySelectorAll('.nav-actions .pill-btn:not(.light)').forEach(b=>b.onclick=()=>navigate('profile'));
  document.getElementById('tryAi').onclick=()=>navigate('ai');
  document.getElementById('searchForm').onsubmit=e=>{e.preventDefault();navigate('search',{q:document.getElementById('searchInput').value.trim()})};
  document.querySelectorAll('.quick button').forEach(b=>b.onclick=()=>navigate('search',{q:b.textContent.replace(' deals','')}));
  window.addEventListener('popstate',render);
  const notify = text => {const t=document.getElementById('toast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)};
  const merchantModal=document.getElementById('merchantModal');
  const studentModal=document.getElementById('studentModal');
  const launchTrack=document.getElementById('launchTrack');
  let launchSlide=0;
  function setLaunchSlide(index){launchSlide=Math.max(0,Math.min(1,index));if(launchTrack)launchTrack.style.transform='translateX(-'+(launchSlide*100)+'%)';document.querySelectorAll('[data-launch-index]').forEach(x=>x.classList.toggle('active',Number(x.dataset.launchIndex)===launchSlide));}
  document.addEventListener('click',e=>{
    const save=e.target.closest('[data-save]');
    if(save){e.preventDefault();e.stopPropagation();save.classList.toggle('saved');save.textContent=save.classList.contains('saved')?'✓ Saved':'Save';notify(save.classList.contains('saved')?'Saved — you will earn points after a completed visit':'Removed from saved')}
    const aiPlan=e.target.closest('[data-ai-plan]');
    if(aiPlan){const user=document.querySelector('#routeView .bubble.user'),title=document.querySelector('#aiPlanResult h2');if(user)user.textContent=aiPlan.dataset.aiPlan;if(title)title.textContent=aiPlan.dataset.aiPlan.includes('200')?'A plan under 200 SEK':aiPlan.dataset.aiPlan.includes('JU')?'Affordable places near JU':'Your nearby plan is ready';notify('Nearby AI updated your plan')}
    const preview=e.target.closest('[data-map-preview]');
    if(preview){const p=jonkopingPlaces.find(x=>x.id===preview.dataset.mapPreview),box=document.getElementById('mapPreview');if(p&&box){box.querySelector('img').src=p.img;box.querySelector('b').textContent=p.name;box.querySelector('small').textContent=p.type+' · '+p.address.split(',')[0];const open=box.querySelector('[data-go]');open.dataset.id=p.id}}
    if(e.target.closest('[data-merchant-open]'))merchantModal.classList.add('open');
    if(e.target.closest('[data-student-open]')){setLaunchSlide(1);studentModal.classList.add('open')}
    if(e.target.closest('[data-go="student"]'))studentModal.classList.remove('open');
    if(e.target.closest('#studentModal [data-go="campaign"]'))studentModal.classList.remove('open');
    if(e.target.closest('[data-launch-next]'))setLaunchSlide(launchSlide+1);
    if(e.target.closest('[data-launch-prev]'))setLaunchSlide(launchSlide-1);
    const launchDot=e.target.closest('[data-launch-index]');if(launchDot)setLaunchSlide(Number(launchDot.dataset.launchIndex));
    const verifyTab=e.target.closest('[data-verify]');
    if(verifyTab){document.querySelectorAll('.verify-tab').forEach(x=>x.classList.toggle('active',x===verifyTab));const email=document.getElementById('verifyEmail'),upload=document.getElementById('verifyUpload');if(email&&upload){email.hidden=verifyTab.dataset.verify!=='email';upload.hidden=verifyTab.dataset.verify!=='upload'}}
    if(e.target.closest('[data-verify-submit]'))notify('Verification code sent to your school email');
    if(e.target.closest('[data-upload-student]'))notify('Student ID upload mockup opened');
    const toggle=e.target.closest('.toggle');if(toggle)toggle.classList.toggle('active');
    const authTab=e.target.closest('[data-auth-tab]');if(authTab){document.querySelectorAll('[data-auth-tab]').forEach(x=>x.classList.toggle('active',x===authTab));const action=document.querySelector('[data-auth-continue]');if(action)action.textContent=authTab.dataset.authTab==='create'?'Create account':'Sign in'}
    if(e.target.closest('[data-auth-continue]'))notify('Account ready — you can now edit your profile');
    const avatar=e.target.closest('[data-avatar]');if(avatar){document.getElementById('profileAvatar').textContent=avatar.dataset.avatar;document.querySelectorAll('[data-avatar]').forEach(x=>x.classList.toggle('active',x===avatar))}
    if(e.target.closest('[data-save-profile]')){const name=document.getElementById('profileNameInput').value.trim()||'Nearby user';document.getElementById('profileName').textContent=name;notify('Profile updated')}
    const unlock=e.target.closest('[data-pro-unlock]');if(unlock){unlock.textContent='✓ Pro unlocked';unlock.disabled=true;notify(unlock.dataset.proUnlock==='business'?'Business Pro unlocked — insights are ready':'Nearby Pro unlocked — welcome!');if(unlock.dataset.proUnlock==='business')setTimeout(()=>navigate('business-dashboard'),900)}
    if(e.target.matches('[data-search-route]')&&e.key==='Enter')navigate('search',{q:e.target.value.trim()});
    const mapChoice=e.target.closest('[data-map-choice]');
    if(mapChoice){const modal=document.getElementById('mapModal');modal.dataset.google=mapChoice.dataset.google;modal.dataset.apple='https://maps.apple.com/?q='+encodeURIComponent(mapChoice.dataset.address);document.getElementById('mapAddress').textContent=mapChoice.dataset.address;modal.classList.add('open')}
    const method=e.target.closest('.pay-method');
    if(method){document.querySelectorAll('.pay-method').forEach(x=>x.classList.remove('active'));method.classList.add('active');const action=document.getElementById('confirmBooking');if(action)action.textContent='Confirm with '+method.dataset.method;const fields=document.querySelector('.method-fields');if(fields)fields.innerHTML=method.dataset.method==='Card'?'<div class="field"><label>Card number</label><input placeholder="•••• •••• •••• ••••"></div>':'<div class="translation-note">You will continue securely in '+method.dataset.method+' after confirmation.</div>'}
    if(e.target.id==='confirmBooking'){e.target.textContent='✓ Booking confirmed';e.target.style.background='#267b3a';e.target.disabled=true;notify('Your booking and payment offer are confirmed')}
    if(e.target.textContent==='Post'||e.target.textContent==='Reply')notify('Mockup: your post is ready to publish');
  });
  document.getElementById('merchantClose').onclick=()=>merchantModal.classList.remove('open');
  document.getElementById('merchantLater').onclick=()=>merchantModal.classList.remove('open');
  document.getElementById('merchantStart').onclick=()=>{merchantModal.classList.remove('open');notify('Registration mockup started')};
  merchantModal.onclick=e=>{if(e.target===merchantModal)merchantModal.classList.remove('open')};
  document.getElementById('studentClose').onclick=()=>studentModal.classList.remove('open');
  document.getElementById('studentLater').onclick=()=>studentModal.classList.remove('open');
  studentModal.onclick=e=>{if(e.target===studentModal)studentModal.classList.remove('open')};
  let launchTouchStart=0;
  studentModal.addEventListener('touchstart',e=>{launchTouchStart=e.changedTouches[0].clientX},{passive:true});
  studentModal.addEventListener('touchend',e=>{const delta=e.changedTouches[0].clientX-launchTouchStart;if(Math.abs(delta)>55)setLaunchSlide(launchSlide+(delta<0?1:-1))},{passive:true});
  const mapModal=document.getElementById('mapModal');
  document.getElementById('mapClose').onclick=()=>mapModal.classList.remove('open');
  document.getElementById('mapCancel').onclick=()=>mapModal.classList.remove('open');
  document.getElementById('appleMap').onclick=()=>window.open(mapModal.dataset.apple,'_blank','noopener');
  document.getElementById('googleMap').onclick=()=>window.open(mapModal.dataset.google,'_blank','noopener');
  mapModal.onclick=e=>{if(e.target===mapModal)mapModal.classList.remove('open')};
  const langPop=document.getElementById('languagePop');
  const langButton=document.getElementById('language');
  langButton.onclick=e=>{e.stopPropagation();langPop.classList.toggle('open')};
  document.addEventListener('click',e=>{if(!e.target.closest('#languagePop')&&!e.target.closest('#language'))langPop.classList.remove('open')});
  const languageUI={
    en:{name:'English',nav:['Discover','Deals','Community','Cities'],top:'Now exploring <strong>Jönköping</strong> · Real local places and public business information',title:'Jönköping feels closer with <span class="scribble">nearby.</span>',lede:'Find real restaurants, cafés, hotels and things to do around Jönköping — with accurate addresses and one-tap directions.',search:'Search Jönköping places…'},
    sv:{name:'Svenska',nav:['Upptäck','Erbjudanden','Community','Städer'],top:'Utforskar nu <strong>Jönköping</strong> · Riktiga lokala platser och offentlig företagsinformation',title:'Jönköping känns närmare med <span class="scribble">nearby.</span>',lede:'Hitta riktiga restauranger, kaféer, hotell och saker att göra i Jönköping — med korrekta adresser och enkel navigering.',search:'Sök platser i Jönköping…'},
    es:{name:'Español',nav:['Descubrir','Ofertas','Comunidad','Ciudades'],top:'Explorando <strong>Jönköping</strong> · Lugares locales e información pública real',title:'Jönköping se siente más cerca con <span class="scribble">nearby.</span>',lede:'Descubre restaurantes, cafeterías, hoteles y actividades reales en Jönköping con direcciones precisas.',search:'Buscar lugares en Jönköping…'},
    it:{name:'Italiano',nav:['Scopri','Offerte','Community','Città'],top:'Stai esplorando <strong>Jönköping</strong> · Luoghi locali e informazioni pubbliche reali',title:'Jönköping è più vicina con <span class="scribble">nearby.</span>',lede:'Scopri ristoranti, caffè, hotel e attività reali a Jönköping con indirizzi precisi.',search:'Cerca luoghi a Jönköping…'},
    ja:{name:'日本語',nav:['見つける','お得情報','コミュニティ','都市'],top:'現在地：<strong>ヨンショーピング</strong> · 実在するローカルスポットと公開情報',title:'ヨンショーピングをもっと身近に、<span class="scribble">nearby.</span>',lede:'ヨンショーピングの実在するレストラン、カフェ、ホテル、体験を正確な住所から探せます。',search:'ヨンショーピングのお店を検索…'},
    ko:{name:'한국어',nav:['둘러보기','혜택','커뮤니티','도시'],top:'현재 위치: <strong>옌셰핑</strong> · 실제 로컬 장소와 공개 사업자 정보',title:'옌셰핑을 더 가깝게, <span class="scribble">nearby.</span>',lede:'옌셰핑의 실제 레스토랑, 카페, 호텔과 즐길 거리를 정확한 주소로 찾아보세요.',search:'옌셰핑 장소 검색…'}
  };
  function applyLanguage(lang){const copy=languageUI[lang]||languageUI.en;selectedLang=lang;document.documentElement.lang=lang;langButton.textContent=lang.toUpperCase();document.body.classList.toggle('sv-active',lang==='sv');document.querySelectorAll('.language-choice').forEach(x=>x.classList.toggle('active',x.dataset.lang===lang));document.querySelector('.topbar').innerHTML=copy.top;document.querySelectorAll('.links a').forEach((x,i)=>x.textContent=copy.nav[i]);document.querySelector('#homeView h1').innerHTML=copy.title;document.querySelector('#homeView .lede').textContent=copy.lede;document.getElementById('searchInput').placeholder=copy.search;const bar=document.getElementById('autoTranslateBar');if(lang==='en'){bar.hidden=true}else{bar.hidden=false;bar.innerHTML='✓ Whole platform translated to <b>'+copy.name+'</b> — reviews, menus, posts and business details update automatically. <button data-original>View original</button>'}}
  document.querySelectorAll('.language-choice').forEach(choice=>choice.onclick=()=>{const lang=choice.dataset.lang;selectedLang=lang;localStorage.setItem('nearby-language',lang);applyLanguage(lang);notify('Platform language: '+(languageUI[lang]?.name||choice.querySelector('b').textContent));langPop.classList.remove('open')});
  document.addEventListener('click',e=>{if(e.target.matches('[data-original]')){localStorage.setItem('nearby-language','en');applyLanguage('en')}});
  render();
  if(!params().view)setTimeout(()=>{setLaunchSlide(0);studentModal.classList.add('open')},700);
})();
